:"firewatch-history-backfill","schedule":"*/10 * * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-watchdog'',\n    headers := jsonb_build_object(\n      ''Content-Type'',''application/json'',\n      ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n    ),\n    body := ''{}''::jsonb\n  );\n  ","jobname":"firewatch-watchdog","schedule":"7,22,37,52 * * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-source-audit'',\n    headers := jsonb_build_object(\n      ''Content-Type'',''application/json'',\n      ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n    ),\n    body := ''{}''::jsonb\n  );\n  ","jobname":"firewatch-source-audit","schedule":"12 */6 * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-eumetsat-mtg'',\n    headers := jsonb_build_object(''Content-Type'',''application/json'',''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)),\n    body := ''{}''::jsonb, timeout_milliseconds := 60000);\n  ","jobname":"firewatch-eumetsat-mtg","schedule":"8,18,28,38,48,58 * * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-eumetsat-msg'',\n    headers := jsonb_build_object(''Content-Type'',''application/json'',''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)),\n    body := ''{}''::jsonb, timeout_milliseconds := 60000);\n  ","jobname":"firewatch-eumetsat-msg","schedule":"9,24,39,54 * * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https:/