e":"*/15 * * * *"},{"active":true,"command":"\n  select net.http_post(\n    url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-satellite-evidence'',\n    headers := jsonb_build_object(\n      ''Content-Type'',''application/json'',\n      ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n    ),\n    body := ''{}''::jsonb,\n    timeout_milliseconds := 120000\n  );\n  ","jobname":"firewatch-satellite-evidence","schedule":"47 */6 * * *"},{"active":true,"command":"select public.firewatch_notification_integrity_refresh();","jobname":"firewatch-notification-integrity","schedule":"38 * * * *"},{"active":true,"command":"\n      select net.http_post(\n        url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-ua'',\n        headers := jsonb_build_object(\n          ''Content-Type'',''application/json'',\n          ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n        ),\n        body := ''{\"mode\":\"telegram-drain\"}''::jsonb,\n        timeout_milliseconds := 90000\n      );\n    ","jobname":"firewatch-telegram-drain","schedule":"1,11,16,26,31,41,46,56 * * * *"},{"active":true,"command":"select public.firewatch_source_coverage_refresh();","jobname":"firewatch-source-coverage","schedule":"34 * * * *"},{"active":true,"command":"select public.firewatch_source_baseline_refresh();","jobname":"firewatch-source-baseline","schedule":"36 * * * *"},{"active":true,"command":"\n    select net.http_post(\n      url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-geo-integrity'',\n      headers := jsonb_build_object(\n        ''Content-Type'',''application/json'',\n        ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n      ),\n      body := ''{}''::jsonb,\n      timeout_milliseconds := 90000\n    );\n    ","jobname":"firewatch-geo-integrity","schedule":"39 * * * *"},{"active":true,"command":"\n      select net.http_post(\n        url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-ghsl'',\n        headers := jsonb_build_object(\n          ''Content-Type'',''application/json'',\n          ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n        ),\n        body := ''{}''::jsonb,\n        timeout_milliseconds := 90000\n      );\n    ","jobname":"firewatch-ghsl","schedule":"45 * * * *"},{"active":true,"command":"\n      select net.http_post(\n        url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-event-osint'',\n        headers := jsonb_build_object(\n          ''Content-Type'',''application/json'',\n          ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n        ),\n        body := ''{}''::jsonb,\n        timeout_milliseconds := 90000\n      );\n    ","jobname":"firewatch-event-osint","schedule":"7,17,27,37,47,57 * * * *"},{"active":true,"command":"\n      select net.http_post(\n        url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-telegram-osint'',\n        headers := jsonb_build_object(\n          ''Content-Type'',''application/json'',\n          ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n        ),\n        body := ''{}''::jsonb,\n        timeout_milliseconds := 90000\n      );\n    ","jobname":"firewatch-telegram-osint","schedule":"3,13,23,33,43,53 * * * *"},{"active":true,"command":"\n      select net.http_post(\n        url := ''https://swvpqroxbsrmxdmedojd.supabase.co/functions/v1/firewatch-neptun'',\n        headers := jsonb_build_object(\n          ''Content-Type'',''application/json'',\n          ''x-cron-secret'',(select decrypted_secret from vault.decrypted_secrets where name=''firewatch_cron_secret'' limit 1)\n        ),\n        body := ''{}''::jsonb,\n        timeout_milliseconds := 90000\n      );\n    ","jobname":"firewatch-neptun","schedule":"*/5 * * * *"}]'::jsonb) as x(jobname text,schedule text,command text,active boolean) loop
   begin perform cron.unschedule(r.jobname); exception when others then null; end;
   v_cmd:=replace(r.command,'https://swvpqroxbsrmxdmedojd.supabase.co',rtrim(p_project_url,'/'));
   v_id:=cron.schedule(r.jobname,r.schedule,v_cmd);
   if not r.active then update cron.job set active=false where jobid=v_id; end if;
   v_count:=v_count+1;
 end loop;
 return jsonb_build_object('ok',true,'jobs_installed',v_count,'project_url',rtrim(p_project_url,'/'));
end $fn$;
